#include <print>
#include <vector>

int main() {
    std::vector<int> v = {1, 2, 4, 6, 8, 11, 15};      // 必须有序

    {   // 第一跑：target 取 100
        int target = 100;
        int lo = 0, hi = static_cast<int>(v.size()) - 1;
        bool found = false;
        int steps = 0;
        while (lo < hi) {
            int sum = v[lo] + v[hi];
            ++steps;
            std::println("第 {} 步 lo={} hi={} 和 {}", steps, lo, hi, sum);
            if (sum == target) { found = true; break; }
            if (sum < target) ++lo; else --hi;
        }
        if (found) std::println("找到 {} + {}", v[lo], v[hi]);
        else std::println("没有两个数能凑出 {}", target);
        // 六步一路都和小，最后 lo 撞上 hi 才退出
    }
    {   // 第二跑：target 取 6
        int target = 6;
        int lo = 0, hi = static_cast<int>(v.size()) - 1;
        bool found = false;
        int steps = 0;
        while (lo < hi) {
            int sum = v[lo] + v[hi];
            ++steps;
            std::println("第 {} 步 lo={} hi={} 和 {}", steps, lo, hi, sum);
            if (sum == target) { found = true; break; }
            if (sum < target) ++lo; else --hi;
        }
        // 6 那一跑走满 6 步，命中时 lo=1、hi=2
        std::println("命中时 lo={} hi={}", lo, hi);
    }
    return 0;
}

